/**
 * Normalizes input string for search and dictionary lookup
 */
window.normalizeJapaneseWord = function(rawWord) {
  if (!rawWord) return "";
  return rawWord
    .trim()
    .replace(/[、。！？「」『』（）…・\s]/g, "");
};

/**
 * Intelligent morphological and dictionary lookup for Japanese words
 */
window.lookupJapaneseWord = function(rawWord) {
  if (!rawWord) return null;
  const clean = window.normalizeJapaneseWord(rawWord);
  if (!clean) return null;

  // 1. Direct dictionary match
  if (window.JAPANESE_VOCAB_DB[clean]) {
    return {
      word: clean,
      cleanWord: clean,
      ...window.JAPANESE_VOCAB_DB[clean]
    };
  }

  // 2. Case-insensitive / kana search
  const lowerClean = clean.toLowerCase();
  for (const [key, entry] of Object.entries(window.JAPANESE_VOCAB_DB)) {
    if (key.toLowerCase() === lowerClean ||
        (entry.kana && entry.kana.replace(/\s+/g, '') === clean) ||
        (entry.romaji && entry.romaji.toLowerCase().replace(/[-'\s]/g, '') === lowerClean.replace(/[-'\s]/g, ''))) {
      return {
        word: key,
        cleanWord: key,
        ...entry
      };
    }
  }

  // 3. Particle stripping (handles words clicked with attached particles)
  const particles = ["は", "が", "を", "に", "へ", "で", "と", "も", "の", "から", "まで", "より", "ね", "よ", "か", "だ", "です"];
  for (const p of particles) {
    if (clean.length > p.length && clean.endsWith(p)) {
      const stem = clean.slice(0, -p.length);
      if (window.JAPANESE_VOCAB_DB[stem]) {
        const entry = window.JAPANESE_VOCAB_DB[stem];
        return {
          word: clean,
          cleanWord: stem,
          ...entry,
          en: `${entry.en} (+ particle「${p}」)`
        };
      }
    }
  }

  // 4. Kanji decomposition (synthesizes meaningful definitions from constituent Kanji)
  const kanjiList = [];
  for (const c of clean) {
    if (window.JAPANESE_KANJI_DB && window.JAPANESE_KANJI_DB[c]) {
      kanjiList.push({ char: c, ...window.JAPANESE_KANJI_DB[c] });
    }
  }
  if (kanjiList.length > 0) {
    return {
      word: clean,
      cleanWord: clean,
      kana: clean,
      romaji: clean,
      en: "Compound word composed of: " + kanjiList.map(k => `${k.char} (${k.meaning})`).join(" + "),
      pos: "漢字熟語 (Kanji Compound)",
      jlpt: "N3",
      kanji: kanjiList
    };
  }

  // 5. Meaningful fallback for pure Kana
  return {
    word: clean,
    cleanWord: clean,
    kana: clean,
    romaji: clean,
    en: `Japanese expression: ${clean}`,
    pos: "語句・表現 (Expression)",
    jlpt: "N5",
    kanji: []
  };
};

/**
 * Multi-word or phrase lookup
 */
window.lookupJapanesePhrase = function(phrase) {
  const clean = window.normalizeJapaneseWord(phrase);
  if (window.JAPANESE_VOCAB_DB[clean]) {
    return {
      word: phrase,
      cleanWord: clean,
      ...window.JAPANESE_VOCAB_DB[clean]
    };
  }
  return {
    word: phrase,
    cleanWord: clean,
    kana: clean,
    romaji: phrase,
    en: `Japanese phrase / collocation: ${phrase}`,
    pos: "連語・慣用句 (Phrase / Collocation)",
    jlpt: "N4",
    kanji: []
  };
};

/**
 * Returns phonetic kana info
 */
window.getKanaInfo = function(char) {
  for (const list of [window.JAPANESE_KANA_DATA.hiragana, window.JAPANESE_KANA_DATA.katakana]) {
    const item = list.find(k => k.kana === char);
    if (item && item.romaji) return item;
  }
  return null;
};
